/**
 * AutumnPondScene — the full autumn pond, ported from the design study.
 *
 * This is the faithful port: every layer, every animal, the six-phase sky and
 * the study's own colour grading. ~3,500 SVG elements, ~130 independently
 * animated. It is the heavy option on purpose — AutumnPondBackdrop.tsx is the
 * trimmed one if this proves too much on phones.
 *
 * Self-contained: React only, no CSS file, no imported assets, no absolute URLs
 * (safe under /PhotoPortfolio/).
 *
 * COST, stated plainly so it is an informed choice:
 *   - grading="faithful" applies an SVG colour-matrix filter to the whole
 *     animated scene (this is how the study grades dawn/sunset/evening/night).
 *     A filter over moving content is the most expensive thing in this file.
 *     grading="tint" swaps it for a flat colour overlay: much cheaper, close
 *     but not identical. grading="none" leaves the palette ungraded.
 *   - Each animal carries an feMorphology ink outline, as drawn in the study.
 *     ink={false} drops them.
 *   - The moon layer uses mix-blend-mode: screen.
 *   - Animations pause on tab-hide and whenever paused is true. Pass paused
 *     while a photo lightbox is open.
 *   - prefers-reduced-motion stops every animation; the crossing animals are
 *     parked at distinct spots so the scene reads as a still tableau.
 */
import { useEffect, useState } from "react";

export type PondPhase = "dawn" | "sunrise" | "afternoon" | "sunset" | "evening" | "night";
export type PondGrading = "faithful" | "tint" | "none";

export interface AutumnPondSceneProps {
  /** Time of day. Explicit prop — this never reads the visitor's clock. */
  phase?: PondPhase;
  /** How the time-of-day grade is applied. See the cost note above. */
  grading?: PondGrading;
  /** Ink outlines on the animals, as drawn in the study. */
  ink?: boolean;
  /** Force the lamps lit regardless of phase. */
  lampsLit?: boolean;
  /** Stacking order of the fixed layer. Page content should sit above it. */
  zIndex?: number;
  /** 0–1 legibility veil over the sky. Defaults per phase. */
  scrim?: number;
  /** Freeze all motion. */
  paused?: boolean;
  className?: string;
}

interface Phase {
  skyTop: string; skyMid: string; skyLow: string; horizonGlow: string; water: string;
  sunLift: number; sunVis: number; sunRim: string; sunMid: string; sunCore: string;
  rayFill: string; rayVis: number; rayLowVis: number;
  star: number; moon: number; meteor: number; cloudFill: string;
  moonX: number; moonY: number; lamp: number; filter: string;
}

