  // painted again in FRONT of them at reduced strength, screen-blended: over
  // clear sky it just deepens the glow, over a cloud it lights the cloud from
  // behind instead of the moon vanishing outright.
  const moonBleed = p.moon * 0.42;
  const tint = TINTS[phase];
  const veil = SCRIMS[phase];
